import numpy as np

def get_dists(file_str):
    lines = file_str.strip().split('\n')
    idx = 0
    while idx < len(lines):
        if lines[idx].startswith('c048'):
            break
        idx += 1
    if idx == len(lines): return

    a = np.array([float(x) for x in lines[idx+2].split()])
    b = np.array([float(x) for x in lines[idx+3].split()])
    c = np.array([float(x) for x in lines[idx+4].split()])

    cell = np.vstack([a,b,c])

    elements = lines[idx+5].split()
    counts = [int(x) for x in lines[idx+6].split()]

    coords = []
    atoms = []
    idx += 8
    for i, el in enumerate(elements):
        for _ in range(counts[i]):
            frac = np.array([float(x) for x in lines[idx].split()[:3]])
            coords.append(frac)
            atoms.append(el)
            idx += 1

    coords = np.array(coords)
    for i in range(len(coords)):
        for j in range(i+1, len(coords)):
            for dx in [-1,0,1]:
                for dy in [-1,0,1]:
                    for dz in [-1,0,1]:
                        shift = np.array([dx,dy,dz])
                        vec = (coords[j] + shift - coords[i]) @ cell
                        dist = np.linalg.norm(vec)
                        if dist < 3.5:
                            print(f"{atoms[i]}-{atoms[j]}: {dist:.2f}")

get_dists(open('cdft_topo_pool.csv').read())

